```
The mathematical rule behind Maria's sequence is that each number is the sum of the previous three numbers in the sequence. The first three numbers are 2, 3, and 5, and then each subsequent number is the sum of the previous three numbers.
To modify the program to find the nth number in the sequence, you can simply add a variable to keep track of the current index and break out of the loop when you reach the desired index. Here's an example code:
```c++
#include <iostream>
#include <cmath>
using namespace std;
int main() {
    int n;
    cout << "Enter the length of the sequence: ";
    cin >> n;

    int a = 2;
    int b = 3;
    int c = 5;

    if (n == 1) {
        cout << a << endl;
        return 0;
    }

    if (n == 2) {
        cout << a << " " << b << endl;
        return 0;
    }

    if (n == 3) {
        cout << a << " " << b << " " << c << endl;
        return 0;
    }

    int index = 4;
    int d;

    cout << a << " " << b << " " << c << " ";

    while (index <= n) {
        d = a + b + c;
        cout << d << " ";
