func generateMetaphor(nouns: [String], adjectives: [String], templates: [String]) -> String? {
    guard !nouns.isEmpty && !adjectives.isEmpty && !templates.isEmpty else {
        return nil // handle empty arrays
    }
    guard templates.allSatisfy({ $0.contains("%noun%") && $0.contains("%adjective%") }) else {
        return nil // handle invalid templates
    }
    let randomTemplate = templates.randomElement()!
    let randomNoun = nouns.randomElement()!
    let randomAdjective = adjectives.randomElement()!
    return randomTemplate.replacingOccurrences(of: "%noun%", with: randomNoun)
                          .replacingOccurrences(of: "%adjective%", with: randomAdjective)
}
```
This function takes three parameters: `nouns` and `adjectives` are arrays of strings representing the possible nouns and adjectives to use in the metaphors, respectively; `templates` is an array of strings representing the possible templates to use for the metaphors. Each template should contain the placeholders `%noun%` and `%adjective%` to be replaced with the randomly selected noun and adjective, respectively.
The function first checks that none of the arrays are empty, and that all the templates contain the required placeholders. If any of these conditions are not met, the function returns `nil`.
If the parameters are valid, the function selects a random template from the `templates` array, and replaces the `%noun%` and `%adjective%` placeholders with random elements from the `nouns` and `adjectives` arrays, respectively. The resulting string is then returned.
