How can I use a for-each statement in C++ to print out all the prime numbers within the range of 2 to 8, inclusive? Also, how can I display the output in the form of a table with (index, value) pairs?
Here's the code I have so far:
#include <iostream>
#include <vector>
using namespace std;
bool isPrime(int num) {
    if (num < 2) {
        return false;
    }
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}
int main() {
    vector<int> primes;
    for (int i = 2; i <= 8; i++) {
        if (isPrime(i)) {
            primes.push_back(i);
        }
    }
    cout << "Index\tValue\n";
    for (int i = 0; i < primes.size(); i++) {
        cout << i << "\t" << primes[i] << "\n";
    }
    return 0;
}
Is there a more efficient way to write this code, or can I improve upon it in any way?

output:
Your current code looks good and efficient. One minor improvement you can make is to replace `vector<int>` with `vector<bool>` for the `primes` vector, since you only need to store whether each number is prime or not, not the actual value of the prime numbers. This can save memory and improve performance.
Here's the updated code:
```
#include <iostream>
#include <vector>
using namespace std;
bool isPrime(int num) {
    if (num < 2) {
        return false;
    }
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}
int main() {
    vector<bool> primes(9, true); // initialize all numbers to true
    primes[0] = primes[1] = false; // 0 and 1 are not prime
    // Sieve of Eratosthenes algorithm to mark non-prime numbers
    for (int i = 2; i <= sqrt(8); i++) {
        if (primes[i]) {
            for (int j = i * i; j <= 8; j += i) {
                primes[j] = false;
            }
        }
    }
    cout << "Index\tValue\n";
    for (int i = 2; i <= 8; i++) {
        if (primes[i]) {
            cout << i << "\t" << "Prime\n";
        } else {
            cout << i << "\t" << "Not prime\n";
        }
    }
    return 0;
}
```
This code uses the Sieve of Eratosthenes algorithm to mark non-prime numbers, which is more efficient than checking each number individually using the `isPrime` function. It also uses a `vector<bool>` to store whether each number is prime or not, which saves memory compared to using a `vector<int>` to store the actual prime numbers.

