Design an algorithm to solve the Eight Queens puzzle using backtracking. You must implement the algorithm in [Java code] data format. The Eight Queens puzzle is a classic chess problem in which a chess board must be filled with eight queens, with no two queens attacking each other. The problem can be solved using a recursive backtracking algorithm that tries to place one queen at a time, and then checks if the board is still valid. Here is some starter code to get you started:
public class EightQueens {
    private static final int BOARD_SIZE = 8;
    private static final int[] rows = new int[BOARD_SIZE];
    public static void main(String[] args) {
        solve(0);
    }
    private static void solve(int row) {
        if (row == BOARD_SIZE) {
            printBoard();
            return;
        }
        for (int col = 0; col < BOARD_SIZE; col++) {
            if (isValid(row, col)) {
                rows[row] = col;
                solve(row + 1);
            }
        }
    }
    private static boolean isValid(int row, int col) {
        for (int i = 0; i < row; i++) {
            int otherCol = rows[i];
            if (otherCol == col || Math.abs(otherCol - col) == row - i) {
                return false;
            }
        }
        return true;
    }
    private static void printBoard() {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (rows[i] == j) {
                    System.out.print("Q ");
                } else {
                    System.out.print(". ");
                }
            }
            System.out.println();
        }
        System.out.println();
    }
}

