Here's an updated function that can handle arrays with different data types and detect circular references within object data types:
```python
def find_value_in_array(arr, val, visited=[]):
    for i, item in enumerate(arr):
        if isinstance(item, list):
            if id(item) in visited:
                raise ValueError(f"Circular reference detected at index {i}")
            visited.append(id(item))
            try:
                return find_value_in_array(item, val, visited)
            except ValueError as e:
                visited.pop()
                raise e
        elif isinstance(item, dict):
            if id(item) in visited:
                raise ValueError(f"Circular reference detected at index {i}")
            visited.append(id(item))
            try:
                return find_value_in_dict(item, val, visited)
            except ValueError as e:
                visited.pop()
                raise e
        elif item == val:
            return i
    raise ValueError(f"{val} not found in array")
def find_value_in_dict(dct, val, visited=[]):
    for key, value in dct.items():
        if isinstance(value, list):
            if id(value) in visited:
                raise ValueError(f"Circular reference detected at key {key}")
            visited.append(id(value))
            try:
                return find_value_in_array(value, val, visited)
            except ValueError as e:
                visited.pop()
                raise e
        elif isinstance(value, dict):
            if id(value) in visited:
                raise ValueError(f"Circular reference detected at key {key}")
            visited.append(id(value))
            try:
                return find_value_in_dict(value, val, visited)
            except ValueError as e:
                visited.pop()
                raise e
        elif value == val:
            return key
    raise ValueError(f"{val} not found in dictionary")
```
The `visited` list keeps track of the objects that have already been visited to detect circular references. The `id()` function is used to get a unique identifier for each object in memory. If an object is already in the `visited` list, it means there is a circular reference and a `ValueError` is raised with the location of the circular reference. 
This updated function can handle arrays with different data types and detect and handle circular references within object data types.

