Sure, here is a JavaScript code that generates a random set of 5 adjectives to describe a summer day without any repetition:
```
const adjectives = ['sunny', 'hot', 'bright', 'relaxing', 'vibrant', 'refreshing', 'breezy', 'colorful', 'cheerful', 'blissful', 'invigorating', 'idyllic', 'picturesque', 'serene', 'tranquil'];
function getRandomAdjectives(num) {
  const result = [];
  while (result.length < num) {
    const randomAdj = adjectives[Math.floor(Math.random() * adjectives.length)];
    if (!result.includes(randomAdj)) {
      result.push(randomAdj);
    }
  }
  return result;
}
const summerDayAdjectives = getRandomAdjectives(5);
console.log(summerDayAdjectives);
